 "content": "def transform(grid):
    """Stamp every all-zero translated occurrence of the marker's shape."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next((v for row in grid for v in row if v not in (0, 2, 8)), None)
    if marker is None:
        return out
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    min_r = min(r for r, _ in points); min_c = min(c for _, c in points)
    shape = [(r-min_r, c-min_c) for r, c in points]
    sh = max(r for r, _ in shape) + 1; sw = max(c for _, c in shape) + 1
    for r0 in range(h-sh+1):
        for c0 in range(w-sw+1):
            cells = [(r0+dr, c0+dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = marker
    return out


